import os, re, json, html, urllib.request
from html.parser import HTMLParser
from pathlib import Path

URLS = [
    ("Do Things that Don't Scale", "https://www.paulgraham.com/ds.html"),
    ("Founder Mode", "https://www.paulgraham.com/foundermode.html"),
]

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.chunks = []
        self._ignore = False
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style'):
            self._ignore = True
            return
        if tag in ('p','br','tr','div','h1','h2','h3','li','blockquote','title'):
            self.chunks.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script','style'):
            self._ignore = False
            return
        if tag in ('p','tr','div','li','h1','h2','h3','blockquote'):
            self.chunks.append('\n')
    def handle_data(self, data):
        if not self._ignore:
            self.chunks.append(data)


def extract_text(html_text: str) -> str:
    parser = TextExtractor()
    parser.feed(html_text)
    text = html.unescape(''.join(parser.chunks))
    text = re.sub(r'[ \t\r\f\v]+', ' ', text)
    text = re.sub(r'\n\s*\n\s*\n+', '\n\n', text)
    return text.strip()


def clean_text(text: str) -> str:
    lines = [line.strip() for line in text.splitlines()]
    filtered = []
    skip_phrases = {
        'Want to start a startup? Get funded by',
        'Y Combinator.',
    }
    for line in lines:
        if not line:
            filtered.append('')
            continue
        if line in skip_phrases:
            continue
        # Drop translation footer lines
        if re.fullmatch(r'.*Translation', line):
            continue
        # Drop empty bracket-only lines
        if re.fullmatch(r'\[\d+\]', line):
            # keep footnote markers if embedded in paragraphs; standalone markers are noise
            continue
        filtered.append(line)

    # Collapse multiple blank lines
    out_lines = []
    blank = False
    for line in filtered:
        if line == '':
            if not blank:
                out_lines.append('')
            blank = True
        else:
            out_lines.append(line)
            blank = False

    # Remove leading/trailing blanks
    while out_lines and out_lines[0] == '':
        out_lines.pop(0)
    while out_lines and out_lines[-1] == '':
        out_lines.pop()

    return '\n'.join(out_lines)


def chunk_text(text: str, max_chars: int = 3500):
    # Split by sentences while keeping punctuation.
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    cur = ''
    for s in sentences:
        if not s:
            continue
        if len(cur) + len(s) + 1 <= max_chars:
            cur = (cur + ' ' + s).strip()
        else:
            if cur:
                chunks.append(cur)
            if len(s) <= max_chars:
                cur = s
            else:
                # fallback: hard wrap overly long sentence
                for i in range(0, len(s), max_chars):
                    part = s[i:i+max_chars]
                    if part:
                        chunks.append(part)
                cur = ''
    if cur:
        chunks.append(cur)
    return chunks


def fetch_essay(title, url):
    html_bytes = urllib.request.urlopen(url).read()
    try:
        html_text = html_bytes.decode('utf-8')
    except UnicodeDecodeError:
        html_text = html_bytes.decode('latin-1')
    text = extract_text(html_text)
    text = clean_text(text)
    # Ensure title at top
    if not text.lower().startswith(title.lower()):
        text = f"{title}\n\n" + text
    return text


essays = []
for title, url in URLS:
    essays.append((title, url, fetch_essay(title, url)))

combined = []
for title, url, text in essays:
    combined.append(f"{title}\n")
    combined.append(text)
    combined.append('\n\n')
combined_text = ''.join(combined).strip()

chunks = chunk_text(combined_text, max_chars=3500)

out_dir = Path('/root/tts_chunks')
out_dir.mkdir(exist_ok=True)

api_key = os.environ.get('OPENAI_API_KEY', '')
if not api_key:
    raise SystemExit('OPENAI_API_KEY not set')

# Call OpenAI TTS for each chunk
for i, chunk in enumerate(chunks, 1):
    payload = json.dumps({
        'model': 'gpt-4o-mini-tts',
        'voice': 'alloy',
        'input': chunk,
    }).encode('utf-8')
    req = urllib.request.Request(
        'https://api.openai.com/v1/audio/speech',
        data=payload,
        headers={
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json',
        },
        method='POST',
    )
    out_path = out_dir / f"chunk_{i:03d}.mp3"
    with urllib.request.urlopen(req) as resp:
        audio = resp.read()
    out_path.write_bytes(audio)
    print(f"wrote {out_path}")

print(f"Total chunks: {len(chunks)}")
